<?php require_once 'includes/bootstrap.php'; $pdo=db();$media=$pdo->query("SELECT title,image,short_description FROM courses WHERE is_active=1 ORDER BY id")->fetchAll(); page_head('Media & Learning Gallery','Explore learning visuals from the Learn with Nazmul course catalogue.');site_header('media.php'); ?>
<main><section class="page-hero"><div class="page-hero-content"><p class="section-label">MEDIA & LEARNING GALLERY</p><h1>Explore the learning environment</h1><p>Click a thumbnail to view a larger course image and its description.</p></div></section><section><div class="media-viewer"><figure class="featured-media"><img id="featuredImage" src="<?= e(url('images/'.$media[0]['image']??'hero-learning.jpg')) ?>" alt="Featured learning image"><figcaption id="featuredCaption"><?= e($media[0]['short_description']??'Flexible digital learning resources.') ?></figcaption></figure><div class="thumbnail-grid" role="list" aria-label="Learning image thumbnails"><?php foreach($media as $i=>$m): ?><button class="thumbnail-button<?= $i===0?' active':'' ?>" type="button" role="listitem" data-image="<?= e(url('images/'.$m['image'])) ?>" data-alt="Course image for <?= e($m['title']) ?>" data-caption="<?= e($m['short_description']) ?>" aria-label="View <?= e($m['title']) ?> image"><img src="<?= e(url('images/'.$m['image'])) ?>" alt=""></button><?php endforeach; ?></div></div></section></main><?php site_footer(); ?>